import json,sys,random,time
sys.path.insert(0,'/app');from tools.check_schedule import clear_of,minutes
wf,seedfile,out,target,secs,seed=sys.argv[1],sys.argv[2],sys.argv[3],int(sys.argv[4]),float(sys.argv[5]),int(sys.argv[6]);random.seed(seed);w=json.load(open(wf));raw=json.load(open(seedfile));ps=w['presses'];jobs=w['jobs'];J={j['id']:j for j in jobs};ids=[p['id'] for p in ps]
def pc(i,q):
 p=ps[i];clock=0;fam=p['initial_family'];c=0
 for x in q:
  j=J[x];ch=w['setup_minutes'][fam][j['family']];cs=clear_of(clock,ch,p['maintenance']);rt=minutes(j,p);st=clear_of(max(cs+ch,j['release']),rt,p['maintenance']);clock=st+rt;c+=40*ch+j['weight']*max(0,clock-j['due']);fam=j['family']
 return c
# Capture ordered run topology and original contents.
top=[]
for i,pid in enumerate(ids):
 q=raw['presses'].get(pid,[]);slots=[];a=0
 while a<len(q):
  f=J[q[a]]['family'];b=a+1
  while b<len(q) and J[q[b]]['family']==f:b+=1
  slots.append((f,q[a:b]));a=b
 top.append(slots)
def flatten(slots):return [x for _,q in slots for x in q]
def total(slots):return sum(pc(i,flatten(slots[i])) for i in range(len(ps)))
best=10**30;bestslots=None;end=time.time()+secs;it=0
while time.time()<end and best>target:
 it+=1; slots=[];used=set()
 # Seed each run with one compatible job from its original run; random choice diversifies.
 for i,ss in enumerate(top):
  row=[]
  for f,orig in ss:
   choices=[x for x in orig if x not in used]
   x=random.choice(choices);used.add(x);row.append([f,[x]])
  slots.append(row)
 rem=[j['id'] for j in jobs if j['id'] not in used]
 mode=it%4
 if mode==0:rem.sort(key=lambda x:(J[x]['due'],-J[x]['weight']))
 elif mode==1:rem.sort(key=lambda x:(J[x]['due']/J[x]['weight'],J[x]['due']))
 elif mode==2:rem.sort(key=lambda x:(J[x]['family'],J[x]['due']))
 else:random.shuffle(rem)
 costs=[pc(i,flatten(slots[i])) for i in range(len(ps))]
 for x in rem:
  opts=[];f=J[x]['family']
  for i,row in enumerate(slots):
   if J[x]['tonnage']>ps[i]['tonnage']:continue
   for k,(sf,q) in enumerate(row):
    if sf!=f:continue
    for pos in range(len(q)+1):
     nq=q[:pos]+[x]+q[pos:];old=row[k][1];row[k][1]=nq;c=pc(i,flatten(row));row[k][1]=old;opts.append((c-costs[i]+random.random()*(30 if mode==3 else 0),c,i,k,pos))
  _,c,i,k,pos=min(opts);slots[i][k][1].insert(pos,x);costs[i]=pc(i,flatten(slots[i]))
 c=sum(costs)
 if c<best:
  best=c;bestslots=[[ [f,q[:]] for f,q in row] for row in slots];sched={'presses':{ids[i]:flatten(bestslots[i]) for i in range(len(ids))}};json.dump(sched,open(out,'w'),indent=1);print('BEST',best,'iter',it,flush=True)
print('FINAL',best,it)
